def parse_json_lines(chunks):
    import codecs
    import json
    import math
    def unique(pairs):
        d = {}
        for k, v in pairs:
            if k in d: raise ValueError('duplicate key')
            d[k] = v
        return d
    def number(text):
        x = float(text)
        if not math.isfinite(x): raise ValueError('nonfinite')
        return x
    def integer(text):
        if len(text.lstrip('-')) > 4000: raise ValueError('integer exceeds 4000 digits')
        return int(text)
    def bad(_): raise ValueError('nonfinite')
    decoder = codecs.getincrementaldecoder('utf-8')('strict')
    remaining = ''
    out = []
    def consume(line):
        if line.strip(): out.append(json.loads(line, object_pairs_hook=unique, parse_constant=bad, parse_float=number, parse_int=integer))
    try:
        for part in chunks:
            if not isinstance(part, bytes): raise ValueError('chunks must be bytes')
            remaining += decoder.decode(part)
            while '\n' in remaining:
                line, remaining = remaining.split('\n', 1)
                consume(line)
        remaining += decoder.decode(b'', final=True)
        consume(remaining)
    except (UnicodeError, TypeError) as e:
        raise ValueError('invalid input') from e
    return out

