def decimal_totals(amounts):
    from decimal import Decimal, localcontext, ROUND_HALF_EVEN
    with localcontext() as ctx:
        ctx.prec = 80
        values = [Decimal(a) for a in amounts]
        if any(not v.is_finite() for v in values): raise ValueError('finite amount required')
        unit = Decimal('0.01')
        rounded = [v.quantize(unit, rounding=ROUND_HALF_EVEN) for v in values]
        def f(x):
            if not x: x = abs(x)
            return format(x, '.2f')
        return {'lines': [f(v) for v in rounded], 'line_total': f(sum(rounded, Decimal(0))), 'end_total': f(sum(values, Decimal(0)).quantize(unit, rounding=ROUND_HALF_EVEN))}

