def dependency_snapshots(nodes, updates):
    import copy
    definitions = copy.deepcopy(nodes)
    def evaluate():
        result, visiting = {}, set()
        def value(key):
            if key in result: return result[key]
            if key in visiting: raise ValueError('cycle')
            if key not in definitions: raise ValueError('missing dependency')
            visiting.add(key)
            node = definitions[key]
            result[key] = node['constant'] if 'constant' in node else sum(weight * value(dep) for dep, weight in node['terms'])
            visiting.remove(key)
            return result[key]
        for key in sorted(definitions): value(key)
        return {key: result[key] for key in sorted(result)}
    snapshots = [evaluate()]
    for patch in updates:
        definitions.update(copy.deepcopy(patch))
        snapshots.append(evaluate())
    return snapshots

