def normalize_relative(path):
    if not isinstance(path, str) or path.startswith('/') or '\x00' in path:
        raise ValueError('relative path required')
    parts = []
    for p in path.split('/'):
        if p in ('', '.'): continue
        if p == '..':
            if not parts: raise ValueError('escapes root')
            parts.pop()
        else: parts.append(p)
    return '/'.join(parts) or '.'

